SELECT id, order_id, product_id, quantity, unit_price, LAG(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id) AS next_quantity, LEAD(unit_price) OVER (PARTITION BY order_id ORDER BY quantity, id) AS next_unit_price, LAG(unit_price) OVER (PARTITION BY order_id ORDER BY quantity, id) AS prev_unit_price, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY quantity, id) AS row_seq, AVG(unit_price) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS unit_price_avg_2_prior FROM order_items;
